(function() {
  var orderId = input && input.orderId;

  if (!orderId) {
    data.status = 'Missing orderId input';
    return;
  }

  var gr = new GlideRecord('x_1771422_refund_0_refund_details');

  if (gr.get('order_id', orderId)) {
    data.status = gr.status.toString();
  } else {
    data.status = 'Order not found';
  }
})();
